import{_ as a,o as e,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Code Walkthroughs: RADOS Snapshots","description":"","frontmatter":{"title":"Ceph Code Walkthroughs: RADOS Snapshots","date":"2021-04-01T00:00:00.000Z","updated":"2021-04-01T00:00:00.000Z","tags":["Ceph","分布式存储","快照技术","RBD","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Code_Walkthroughs_-_RADOS_Snapshots.md","filePath":"posts/2021/Ceph_Code_Walkthroughs_-_RADOS_Snapshots.md","lastUpdated":1780459816000}'),i={name:"posts/2021/Ceph_Code_Walkthroughs_-_RADOS_Snapshots.md"};function s(r,l,h,n,p,d){return e(),t("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要-ceph-snapshot-技术详解" tabindex="-1">会议纪要：Ceph Snapshot 技术详解 <a class="header-anchor" href="#会议纪要-ceph-snapshot-技术详解" aria-label="Permalink to &quot;会议纪要：Ceph Snapshot 技术详解&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期与时间</strong>：2023年3月23日，17:00 UTC</li><li><strong>主讲人</strong>：Samuel Just</li><li><strong>主题</strong>：Ceph Snapshot 技术详解</li><li><strong>参与人员</strong>：Ceph 社区成员</li><li><strong>会议形式</strong>：在线视频会议</li></ul><h4 id="讨论内容" tabindex="-1">讨论内容 <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容&quot;">​</a></h4><ol><li><p><strong>Snapshot 概述</strong></p><ul><li>Ceph 支持三种项目：RGW, RBD, 和 ZFS，其中 RBD 和 CephFS 大量使用快照功能。</li><li>RBD 在块设备层面使用快照，而 CephFS 在子树层面使用。</li><li>两者都使用 Librados 来管理 I/O，并共享相同的底层快照机制。</li></ul></li><li><p><strong>快照的工作原理</strong></p><ul><li><strong>创建快照</strong>：客户端维护快照元数据，CephFS 通过 MDS 和能力系统进行排序，RBD 则在每个 RBD 块设备的头对象上维护快照信息。</li><li><strong>读取快照</strong>：OSD 维护每个对象的快照状态映射，通过在写操作中附加快照信息来更新。</li><li><strong>回滚快照</strong>：必须逐对象执行，RBD 快照回滚时间与对象数量成线性关系。</li><li><strong>删除快照</strong>：空间回收是懒惰的后台操作。</li></ul></li><li><p><strong>客户端与快照交互</strong></p><ul><li>客户端通过 RBD 或 CephFS 的快照机制与快照交互。</li><li>RBD 在创建快照时，会请求新的快照 ID，并更新头对象的元数据，然后通知所有用户重新加载快照元数据。</li></ul></li><li><p><strong>快照的底层接口</strong></p><ul><li>Librados 提供了四个基本操作：<code>snap create</code>, <code>snap set snap right context</code>, <code>snap remove</code>, 和 <code>snap rollback</code>。</li><li>快照创建和删除主要由监视器操作，OSD 通过接收 OSD 地图更新来处理快照信息。</li></ul></li><li><p><strong>快照的恢复与优化</strong></p><ul><li>恢复过程中，需要先恢复头对象，然后根据快照集信息恢复克隆对象。</li><li>通过计算克隆子集，优化恢复过程中的数据共享，减少空间使用。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>无具体决定事项，主要为技术分享和讨论。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>会议录像将上传至 Ceph 的 YouTube 频道。</li><li>社区成员应关注即将到来的技术讲座和用户调查。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议中提到的 RBD 镜像功能，如快照镜像和稀疏克隆，为虚拟化环境提供了高效的存储解决方案。</li><li>社区成员对快照功能的深入理解有助于更好地利用 Ceph 的存储能力。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>感谢 Samuel Just 的详细讲解和社区成员的积极参与。</li><li>期待下一次的 Ceph 技术分享会议。</li></ul>',13)])])}const _=a(i,[["render",s]]);export{c as __pageData,_ as default};
